# Report the fixed diagnostic decision before changing any preset.
if(dir.exists('.local/R-library')) .libPaths(c(normalizePath('.local/R-library'),.libPaths()))
source('R/scp_calibrate.R');start<-proc.time()[['elapsed']];out<-'reports/J'
s<-read.csv(file.path(out,'decision-table.csv'));depth<-read.csv(file.path(out,'native-depth-summary.csv'));vs<-.scp_versions();vt<-paste(names(vs),vs,sep='=',collapse='; ')
lines<-c('# Diagnostic J — TMT endpoint mask consistency','13 October 2026. Uses the v0.3.0 validation halves and H1 source cells; no preset changes preceded this diagnostic.',
 '\n| Dataset | PSM finite | Endpoint finite | Endpoint sparsity gap | PSM finite / endpoint NA pairs | Median p difference | Median q difference |',
 '| --- | ---: | ---: | ---: | ---: | ---: | ---: |')
for(i in seq_len(nrow(s))){r<-s[i,];lines<-c(lines,sprintf('| %s | %.3f%% | %.3f%% | %.3f pp | %.3f%% | %.5f | %.5f |',r$dataset,100*r$psm_finite_fraction,100*r$aggregated_finite_fraction,100*r$aggregated_sparser_gap,100*r$psm_finite_aggregated_NA_fraction,r$median_p_difference,r$median_q_difference))}
lines<-c(lines,'\n## Decision before any change',
 sprintf('Amendment I applies to both TMT datasets under the fixed rule: the endpoint aggregated matrix is sparser than the PSM mask by %.3f pp in Specht macrophages and %.3f pp in Leduc monocytes, exceeding the 5-pp threshold in each dataset. Detection parameters and the M2 missing-fraction comparison must therefore use the mask of the quantitative assay evaluated by the endpoint. This is an assay-consistency change, not a refit of the noise model or a change to any tolerance. The accepted v0.3.0 M4 verdict stands. M2b must pass on both TMT datasets before M4b proceeds.',100*s$aggregated_sparser_gap[1],100*s$aggregated_sparser_gap[2]),
 '\n## Full comparisons',
 '[Overall and per-tier finite fractions and paired p/q differences](mask-summary-by-tier.csv); [Specht per-protein p/q](specht2019v3-protein-mask-differences.csv); [Leduc per-protein p/q](leduc2022_pSCoPE-protein-mask-differences.csv). Differences are endpoint minus PSM. Rates are estimated on the same validation proteins, source cells and native runs. p is the unweighted fraction of occupied native plexes with any finite protein value; q is quantified channels divided by channels in those identified plexes. The two masks are not nested; reverse discordant pairs are reported as well.',
 '\n## Pipeline attribution',
 'The endpoint finite mask is reproduced exactly from the deposited peptide assay by the registered log transformation and protein median. A PSM-positive / endpoint-NA pair has no finite retained peptide quantity in that assay. The local protein median does not remove a finite included peptide, and no compared cell is removed between the two paired masks. The identifiable loss is upstream of the local protein aggregation: peptide retention/quantification and the producer ratio processing, not a newly applied local cell filter.',
 'Specht’s producer exports Peptides-raw.csv from cr_norm_log(t3), after reference-channel normalisation, cell QC and peptide missing-data filtering. Leduc’s scpdata builder imports a processed peptide table and builds its peptide/protein-group mapping; the two deposited objects do not identify which particular upstream filter removed every discordant pair. We do not assign a filter to a pair without a retention trace. [Pipeline audit](pipeline-audit.csv).',
 'Sources: [Specht producer code](https://github.com/cvanderaa/SCoPE2/blob/master/code/SCoPE2_analysis.R); [Specht scpdata builder](https://github.com/UCLouvain-CBIO/scpdata/blob/master/inst/scripts/make-data_specht2019v3.R); [Leduc scpdata builder](https://github.com/UCLouvain-CBIO/scpdata/blob/master/inst/scripts/make-data_leduc2022_pSCoPE.R). Downloaded source hashes are retained in the existing source manifests.',
 '\n## Native cell-depth variation',
 '| Dataset | Mask | Observed depth SD | Simulated mean depth SD |','| --- | --- | ---: | ---: |')
for(i in seq_len(nrow(depth))){r<-depth[i,];lines<-c(lines,sprintf('| %s | %s | %.2f | %.2f |',r$dataset,r$mask,r$observed_depth_sd,r$simulated_mean_depth_sd))}
lines<-c(lines,'\nDepth is quantified validation proteins per cell. Each mask is compared with twenty native-layout, detection-only G2 replicates using that mask’s own per-protein p/q, fixed protein identities and independent plex/channel Bernoulli draws. TMT masking is intensity-independent, so variance draws are unnecessary for this mask diagnostic. This is a descriptive diagnostic, not a new gate or a calibration half-preset. [Cell depths](specht2019v3-cell-depth.csv), [Leduc depths](leduc2022_pSCoPE-cell-depth.csv), [depth summary](native-depth-summary.csv), [replicate records](depth-replicate-metrics.csv).',
 'Both masks show much greater native cell-depth variation than independent G2 draws. Amendment I addresses the demonstrated assay mismatch; it does not establish that cell/channel dependence is resolved. No dependence term is introduced under this directive.',
 paste0('\nSoftware: ',vt),'\n[Run manifest](run-manifest.json). No M5 work.')
writeLines(lines,file.path(out,'diagnostic-report.md'))
jsonlite::write_json(list(seed=20261013L,versions=as.list(vs),input_hashes=list(diagnostic_manifest=digest::digest(file=file.path(out,'run-manifest.json'),algo='sha256'),decision_table=digest::digest(file=file.path(out,'decision-table.csv'),algo='sha256'),pipeline_audit=digest::digest(file=file.path(out,'pipeline-audit.csv'),algo='sha256')),output_sha256=digest::digest(file=file.path(out,'diagnostic-report.md'),algo='sha256'),wall_seconds=proc.time()[['elapsed']]-start),file.path(out,'report-manifest.json'),pretty=TRUE,auto_unbox=TRUE,digits=NA)
cat('Diagnostic J report issued before amendment I. Both datasets exceed 5 pp.\n')
